function sbLoadWebSound(index, onDone) {
    const entry = SB_SOUNDS[index];
    if (!entry) { onDone && onDone(false); return; }
    if (sbLoading) { currentNotification = 'Already loading...'; notifactionResetTime = time + 2; return; }
    sbLoading = true;
    try {
        Java.perform(() => {
            try {
                const ctx = Java.use('android.app.ActivityThread').currentApplication().getApplicationContext();
                const tmpPath = ctx.getCacheDir().getAbsolutePath() + '/sbsound_' + index + '.mp3';
                const WorkerCls = Java.registerClass({
                    name: 'sb.SoundLoader' + (Date.now() % 100000),
                    implements: [Java.use('java.lang.Runnable')],
                    methods: { run: function() {
                        try {
                            const conn = Java.cast(Java.use('java.net.URL').$new(entry.url).openConnection(), Java.use('java.net.HttpURLConnection'));
                            conn.setConnectTimeout(10000); conn.setReadTimeout(30000); conn.setRequestMethod('GET'); conn.connect();
                            if (conn.getResponseCode() < 200 || conn.getResponseCode() >= 300) { conn.disconnect(); sbLoading = false; onDone && onDone(false); return; }
                            const ins = conn.getInputStream();
                            const buf = Java.array('byte', new Array(8192).fill(0));
                            const fos = Java.use('java.io.FileOutputStream').$new(tmpPath);
                            let n; while ((n = ins.read(buf)) !== -1) fos.write(buf, 0, n);
                            fos.flush(); fos.close(); ins.close(); conn.disconnect();
                            try { if (sbMediaPlayer) { sbMediaPlayer.stop(); sbMediaPlayer.release(); sbMediaPlayer = null; } } catch(_) {}
                            const mp = Java.use('android.media.MediaPlayer').$new();
                            mp.setDataSource(tmpPath); mp.prepare();
                            mp.setVolume(sbVolume, sbVolume); mp.setLooping(sbLoop);
                            sbMediaPlayer = mp; sbLoading = false; onDone && onDone(true);
                        } catch(e) { console.error('[Sound] load err:', e); sbLoading = false; onDone && onDone(false); }
                    }}
                });
                Java.use('java.lang.Thread').$new(WorkerCls.$new()).start();
            } catch(e) { console.error('[Sound] Java err:', e); sbLoading = false; onDone && onDone(false); }
        });
    } catch(e) { console.error('[Sound] err:', e); sbLoading = false; onDone && onDone(false); }
}
function sbPlay() {
    if (!sbMediaPlayer) { currentNotification = 'Load a sound first'; notifactionResetTime = time + 2; return; }
    try { Java.perform(() => { try { sbMediaPlayer.seekTo(0); sbMediaPlayer.start(); } catch(e) { console.error('[Sound] play err:', e); } }); } catch(e) {}
}
function sbStop() {
    if (!sbMediaPlayer) return;
    try { Java.perform(() => { try { sbMediaPlayer.stop(); sbMediaPlayer.prepare(); } catch(_) {} }); } catch(e) {}
}
