function diagnoseError(tag, err) {
    const msg = (err && err.message) ? err.message : String(err);
    const classMatch = msg.match(/couldn't find (?:non-static )?(?:class|type) ([^\s]+)/i)
        ?? msg.match(/class ([^\s]+) not found/i);
    if (classMatch) {
        const cls = classMatch[1];
        return `CLASS NOT FOUND: "${cls}"\n  → The game removed or renamed this class.\n  → Search the dump for "${cls.split(".").pop()}".`;
    }
    const methodMatch = msg.match(/couldn't find (?:non-static )?method ([^\s]+) in (?:hierarchy of )?class ([^\s]+)/i)
        ?? msg.match(/method ([^\s]+) not found in ([^\s]+)/i);
    if (methodMatch) {
        return `METHOD NOT FOUND: "${methodMatch[1]}" on "${methodMatch[2]}"\n  → Check the dump for the new method name.`;
    }
    const fieldMatch = msg.match(/couldn't find field ([^\s]+) in class ([^\s]+)/i)
        ?? msg.match(/field ([^\s]+) not found/i);
    if (fieldMatch) {
        return `FIELD NOT FOUND: "${fieldMatch[1]}" on "${fieldMatch[2] ?? "?"}"\n  → Check the dump for the new field name.`;
    }
    if (msg.includes("isNull") || msg.includes("null reference")) {
        return `NULL REFERENCE\n  → Add: if (!obj || obj.isNull()) return;`;
    }
    return `UNKNOWN ERROR: ${msg}\n  → Check the Frida log for the full stack trace.`;
}
function smartError(tag, err) {
    const fix = diagnoseError(tag, err);
    const msg = (err && err.message) ? err.message : String(err);
    _errorLog.push({ time: Date.now(), tag, msg, fix });
    console.error(`\n╔═ ERROR [${tag}] ═══\n║  ${msg}\n╠═ FIX\n║  ${fix.replace(/\n/g, "\n║  ")}\n╚═══`);
}
// ===== END SMART ERROR =====
