// Unlock All is deliberately serialized to one observable write per frame. The previous implementation
// retained hundreds of bridge wrappers and wrote three observable fields per item, creating a native
// observer storm. Cosmetic ownership uses the engine-provided single override flag.
let _unlockQueue = [], _unlockCursor = 0, _unlockDone = 0;
function processUnlockQueue() {
    if (_unlockCursor >= _unlockQueue.length) return;
    const item = _unlockQueue[_unlockCursor++];
    try {
        if (item && !item.isNull?.()) {
            const state = item.method("get_isUnlocked").invoke();
            if (state && !state.isNull?.()) state.method("set_value").invoke(true);
            _unlockDone++;
        }
    } catch (e) {
        if ((_unlockDone % 64) === 0) console.error("[UnlockAll] queued item:", e);
    }
    if (_unlockCursor >= _unlockQueue.length) {
        const finished = _unlockDone;
        _unlockQueue = [];
        _unlockCursor = 0;
        try { sendNotification("Unlock All: finished (" + finished + " gameplay items)", false); } catch (_) { }
    }
}
