function buildZeroedValueType(t) {
    // Recursively build a nested array of zeros matching a value-type's field layout.
    // Passing this for a struct param avoids "array length does not match number of fields".
    try {
        if (!t || !t.class) return 0;
        if (t.class.isEnum || t.isPrimitive) return 0;
        if (!t.class.isValueType) return null;
        const fields = t.class.fields.filter(f => !f.isStatic);
        if (fields.length === 0) return 0;
        return fields.map(f => buildZeroedValueType(f.type));
    } catch (_) { return 0; }
}
