const arcaneMainThreadTasks = [];
function scheduleArcaneMainThread(delayMs, action, label = "task") {
    if (typeof action !== "function") return;
    if (arcaneMainThreadTasks.length >= 256) arcaneMainThreadTasks.shift();
    arcaneMainThreadTasks.push({ due: Date.now() + Math.max(0, delayMs | 0), action, label });
}
function runArcaneMainThreadTasks() {
    const now = Date.now();
    let processed = 0;
    for (let i = arcaneMainThreadTasks.length - 1; i >= 0 && processed < 16; i--) {
        const task = arcaneMainThreadTasks[i];
        if (!task || task.due > now) continue;
        arcaneMainThreadTasks.splice(i, 1);
        processed++;
        try { task.action(); }
        catch (e) { console.error("[MainThreadTask] " + task.label + ":", e); }
    }
}

// Process-wide singleton guard. Recent WER reports showed several different frida-agent
// modules attached to the same Animal Company process at once; each one installed the same
// hooks and their competing thunks eventually terminated Unity. The named mutex makes all
// later injected copies exit before installing anything, without changing the loader.
let _arcaneAgentMutex = null;
function claimArcaneAgentSingleton() {
    if (typeof Process === "undefined" || Process.platform !== "windows") return true;
    try {
        const kernel = Process.getModuleByName("kernel32.dll");
        const createPtr = kernel.getExportByName("CreateMutexW");
        const errorPtr = kernel.getExportByName("GetLastError");
        const closePtr = kernel.getExportByName("CloseHandle");
        const CreateMutexW = new NativeFunction(createPtr, "pointer", ["pointer", "uint32", "pointer"]);
        const GetLastError = new NativeFunction(errorPtr, "uint32", []);
        const CloseHandle = new NativeFunction(closePtr, "uint32", ["pointer"]);
        const mutexName = Memory.allocUtf16String("Local\\ArcaneACMenu.SingleAgent." + Process.id);
        const handle = CreateMutexW(ptr(0), 0, mutexName);
        if (!handle || handle.isNull()) return true; // fail open on unusual compatibility layers
        const alreadyExists = (GetLastError() >>> 0) === 183; // ERROR_ALREADY_EXISTS
        if (alreadyExists) {
            try { CloseHandle(handle); } catch (_) { }
            console.error("[Arcane] another menu agent is already attached; duplicate injection skipped");
            return false;
        }
        // Intentionally keep this process handle open until the game exits. Hook thunks can
        // outlive a Frida script unload, so allowing a hot reinjection into the same Unity process
        // recreates the exact multi-owner crash. A clean game restart releases the mutex normally.
        _arcaneAgentMutex = handle;
        return true;
    } catch (e) {
        console.error("[Arcane] singleton guard unavailable:", e);
        return true;
    }
}

