    const NUT_SPAM_MODES = {
        SINGLE: 0,
        BURST: 1,
        CONTINUOUS: 2
    };
    // ===== NUT SPAM FUNCTIONS =====
    function spawnNutWithValue(amount, position) {
        try {
            for (let i = 0; i < amount; i++) {
                const offset = {
                    x: (Math.random() - 0.5) * 2,
                    y: 0.5 + Math.random() * 1,
                    z: (Math.random() - 0.5) * 2
                };
                const spawnPos = {
                    x: (position?.x || 0) + offset.x,
                    y: (position?.y || 1) + offset.y,
                    z: (position?.z || 0) + offset.z
                };
                const identityQuaternion = Il2Cpp.domain.assembly("UnityEngine.CoreModule").image.class("UnityEngine.Quaternion").field("identity").value;
                const nutType = Math.random() > 0.5 ? "item_nut" : "item_nut_drop";
                spawnItemAtPos(nutType, spawnPos, identityQuaternion);
            }
        }
        catch (e) {
            console.error("[NUT_SPAM] Error:", e);
        }
    }
    function updateNutSpam() {
        if (!nutSpamEnabled)
            return;
        try {
            const now = Date.now() / 1000;
            const spawnInterval = 1 / (nutSpamSpeed + 0.1);
            if (now >= nutSpamDelay) {
                const localPlayer = NetPlayer.method("get_localPlayer").invoke();
                if (localPlayer && !localPlayer.handle.isNull()) {
                    const playerTransform = localPlayer.method("get_transform").invoke();
                    if (playerTransform && !playerTransform.handle.isNull()) {
                        const playerPos = playerTransform.field("m_LocalPosition").value;
                        switch (nutSpamMode) {
                            case 0:
                                spawnNutWithValue(1, playerPos);
                                break;
                            case 1:
                                spawnNutWithValue(nutSpamAmount, playerPos);
                                break;
                            case 2:
                                for (let i = 0; i < nutSpamAmount; i++) {
                                    spawnNutWithValue(1, playerPos);
                                }
                                break;
                        }
                        nutSpamDelay = now + spawnInterval;
                    }
                }
            }
        }
        catch (e) {
            console.error("[NUT_SPAM] Update error:", e);
        }
    }
    // ===== END NUT SPAM =====
    function stabilizeMobInstance(mob, fallbackPos = null) {
        try {
            if (!mob || mob.isNull?.())
                return;
            let go = mob;
            try {
                const maybeGo = mob.method("get_gameObject").invoke();
                if (maybeGo && !maybeGo.isNull?.())
                    go = maybeGo;
            }
            catch (_) { }
            // Enable the mob object and its network component
            try {
                go.method("SetActive").invoke(true);
            }
            catch (_) { }
            try {
                mob.method("set_enabled").invoke(true);
            }
            catch (_) { }
            // Un-freeze: clear stun fields directly and unlock physics
            try {
                mob.field("_stunDuration").value = 0;
            }
            catch (_) { }
            try {
                mob.field("stunDuration").value = 0;
            }
            catch (_) { }
            try {
                mob.field("_isStunned").value = false;
            }
            catch (_) { }
            try {
                mob.field("isStunned").value = false;
            }
            catch (_) { }
            try {
                mob.method("set_isStunned").invoke(false);
            }
            catch (_) { }
            // Unlock the Rigidbody so physics can move the mob
            try {
                const rb2 = go.method("GetComponentInChildren", 0).inflate(Rigidbody).invoke();
                if (rb2 && !rb2.isNull?.()) {
                    rb2.method("set_isKinematic").invoke(false);
                    rb2.method("set_constraints").invoke(0); // RigidbodyConstraints.None
                }
            }
            catch (_) { }
            // Disable damage/kill triggers so mobs don't get immediately removed
            try {
                const killer = go.method("GetComponentInChildren", 0).inflate(AssemblyCSharp.class("AnimalCompany.ArenaItemKiller")).invoke();
                if (killer && !killer.isNull?.()) {
                    try {
                        killer.method("set_enabled").invoke(false);
                    }
                    catch (_) { }
                    try {
                        killer.field("_isEnabled").value = false;
                    }
                    catch (_) { }
                }
            }
            catch (_) { }
            // Enable NavMeshAgent flags (warp handled by MobController.Spawned hook)
            try {
                const NavMeshAgentClass = Il2Cpp.domain.assembly("UnityEngine.AIModule").image.class("UnityEngine.AI.NavMeshAgent");
                const navAgent = go.method("GetComponentInChildren", 0).inflate(NavMeshAgentClass).invoke();
                if (navAgent && !navAgent.isNull?.()) {
                    try {
                        navAgent.method("set_enabled").invoke(true);
                    }
                    catch (_) { }
                    try {
                        navAgent.method("set_isStopped").invoke(false);
                    }
                    catch (_) { }
                    try {
                        navAgent.method("set_updatePosition").invoke(true);
                    }
                    catch (_) { }
                    try {
                        navAgent.method("set_updateRotation").invoke(true);
                    }
                    catch (_) { }
                }
            }
            catch (_) { }
            // Enable all MonoBehaviour/AI controllers on the mob so it can think and move
            try {
                const behaviours = go.method("GetComponentsInChildren", 0)
                    .inflate(Il2Cpp.domain.assembly("UnityEngine.CoreModule").image.class("UnityEngine.Behaviour"))
                    .invoke();
                if (behaviours && !behaviours.isNull?.()) {
                    const count = behaviours.length;
                    for (let i = 0; i < count; i++) {
                        try {
                            const b = behaviours.get(i);
                            if (!b || b.isNull?.())
                                continue;
                            // Skip renderers/colliders — only enable logic components
                            const typeName = (b.method("GetType").invoke().method("get_Name").invoke()?.content ?? "").toLowerCase();
                            if (typeName.includes("renderer") || typeName.includes("collider") || typeName.includes("itemkiller"))
                                continue;
                            try {
                                b.method("set_enabled").invoke(true);
                            }
                            catch (_) { }
                        }
                        catch (_) { }
                    }
                }
            }
            catch (_) { }
            // Fix position if mob fell into void
            if (fallbackPos) {
                try {
                    const tf = getTransform(go);
                    const cur = tf.method("get_position").invoke();
                    const yVal = cur.field("y").value;
                    if (yVal < -5000 || isNaN(yVal))
                        tf.method("set_position").invoke(fallbackPos);
                }
                catch (_) { }
            }
        }
        catch (e) {
            console.error("[MOB STABILIZE] Error:", e);
        }
    }
    // ── Mob Spawn Delegate helpers ────────────────────────────────────────────────
    let _validatorBypassEnabled = false;
