                    const sx = StartPosition.field("x").value, sy = StartPosition.field("y").value, sz = StartPosition.field("z").value;
                    const ex = EndPosition.field("x").value, ey = EndPosition.field("y").value, ez = EndPosition.field("z").value;
                    const dx = ex - sx, dy = ey - sy, dz = ez - sz;
                    const dist = Math.sqrt(dx * dx + dy * dy + dz * dz) || 0.0001;
                    const nx = dx / dist, ny = dy / dist, nz = dz / dist;
