    let buttonMap = new Map();
    // All keyboard keys for the VR search keyboard
    const KB_ROWS = ["qwertyuiop", "asdfghjkl", "zxcvbnm"];
    const KB_SPECIALS = ["SK_back", "SK_clear", "SK_space", "SK_exit"];
    function getSearchResults() {
        if (hellOreMode) return [];
        if (!searchQuery)
            return buttons.flat().filter(b => !["PreviousPage", "NextPage", "GlobalReturn"].includes(b.buttonText));
        const q = searchQuery.toLowerCase();
        return buttons.flat().filter(b => !["PreviousPage", "NextPage", "GlobalReturn"].includes(b.buttonText) &&
            b.buttonText.toLowerCase().includes(q));
    }
    function rebuildButtonMap() {
        buttonMap = new Map();
        buttons.flat().forEach(button => { buttonMap.set(button.buttonText, button); });
        // Register keyboard key buttons dynamically
        KB_ROWS.forEach(row => {
            for (const ch of row) {
                const key = "SK_" + ch;
                buttonMap.set(key, new ButtonInfo({
                    buttonText: key,
                    isTogglable: false,
                    method: () => {
                        searchQuery += ch;
                        // Rebuild search results in category 20
                        buttons[20] = getSearchResults();
                        currentPage = 0;
                        reloadMenu();
                        sendNotification("Search: " + searchQuery, false);
                    },
                    toolTip: ch
                }));
            }
        });
        // Numbers row
        for (let n = 0; n <= 9; n++) {
            const ch = String(n);
            const key = "SK_" + ch;
            buttonMap.set(key, new ButtonInfo({
                buttonText: key,
                isTogglable: false,
                method: () => {
                    searchQuery += ch;
                    buttons[20] = getSearchResults();
                    currentPage = 0;
                    reloadMenu();
                    sendNotification("Search: " + searchQuery, false);
                },
                toolTip: ch
            }));
        }
        buttonMap.set("SK_back", new ButtonInfo({
            buttonText: "SK_back",
            isTogglable: false,
            method: () => {
                if (searchQuery.length > 0)
                    searchQuery = searchQuery.slice(0, -1);
                buttons[20] = getSearchResults();
                currentPage = 0;
                reloadMenu();
                sendNotification("Search: " + (searchQuery || "(empty)"), false);
            },
            toolTip: "Backspace"
        }));
        buttonMap.set("SK_clear", new ButtonInfo({
            buttonText: "SK_clear",
            isTogglable: false,
            method: () => {
                searchQuery = "";
                buttons[20] = getSearchResults();
                currentPage = 0;
                reloadMenu();
                sendNotification("Search cleared", false);
            },
            toolTip: "Clear search"
        }));
        buttonMap.set("SK_space", new ButtonInfo({
            buttonText: "SK_space",
            isTogglable: false,
            method: () => {
                searchQuery += " ";
                buttons[20] = getSearchResults();
                currentPage = 0;
                reloadMenu();
                sendNotification("Search: " + searchQuery, false);
            },
            toolTip: "Space"
        }));
        buttonMap.set("SK_exit", new ButtonInfo({
            buttonText: "SK_exit",
            isTogglable: false,
            method: () => {
                if (hellOreMode) {
                    if (searchQuery) {
                        spawnHellOreText(searchQuery);
                    }
                    hellOreMode = false;
                    searchActive = false;
                    searchQuery = "";
                    currentCategory = 9;
                    currentPage = 0;
                    reloadMenu();
                    return;
                }
                searchActive = false;
                searchQuery = "";
                currentCategory = 0;
                currentPage = 0;
                reloadMenu();
            },
            toolTip: "Exit search"
        }));
        // Register FAV_ star toggle buttons for every real mod button
        buttons.flat().forEach(btn => {
            if (["PreviousPage", "NextPage", "GlobalReturn", "Search Mods", "Favorites"].includes(btn.buttonText))
                return;
            if (btn.buttonText.startsWith("SK_") || btn.buttonText.startsWith("FAV_"))
                return;
            const favKey = "FAV_" + btn.buttonText;
            buttonMap.set(favKey, new ButtonInfo({
                buttonText: favKey,
                isTogglable: false,
                method: () => {
                    if (favoritedNames.has(btn.buttonText)) {
                        favoritedNames.delete(btn.buttonText);
                        sendNotification("Unfavorited: " + btn.buttonText, false);
                    }
                    else {
                        favoritedNames.add(btn.buttonText);
                        sendNotification("Favorited: " + btn.buttonText, false);
                    }
                    rebuildFavoritesCategory();
                    reloadMenu();
                },
                toolTip: "Toggle favorite:" + btn.buttonText
            }));
        });
    }
    // Category 20: search results — populated dynamically
    buttons[20] = [];
