    buttons[21] = [];
    // ===== CATEGORY 23: DOME TRAP GUN MODS =====
    let domeGunActive = false;
    let domeTrapType = "metalball"; // "metalball", "sellingmachine" or "christmaspresent"
    let domeSize = "medium"; // "small", "medium", "large"
    let domeSpinEnabled = false; // Enable spinning animation
    let domeAutoRelease = 0; // 0=off, 5=5sec, 10=10sec, 20=20sec, 30=30sec
    let domeThickness = "normal"; // "normal", "double", "triple"
    let metalBallColor = "silver"; // "silver", "gold", "red", "blue", "green"
    let selectedDomeTarget = null; // Currently selected player to trap
    let domeSpawnedItems = []; // Track spawned items for cleanup
    // Function to get dome radius based on size
    function getDomeRadius(size) {
        switch (size) {
            case "small": return 1.5;
            case "large": return 3.5;
            default: return 2.5; // medium
        }
    }
    // Function to get layer count based on thickness
    function getLayerCount(thickness) {
        switch (thickness) {
            case "double": return 4;
            case "triple": return 5;
            default: return 3; // normal
        }
    }
    // Function to create a dome of items around a player
    function createDomeTrap(targetPlayer, trapType) {
        try {
            if (!targetPlayer || targetPlayer.handle.isNull()) {
                sendNotification("Invalid target!", false);
                return;
            }
            // Show gun pointer line when firing dome
            if (domeGunActive) {
                renderGun();
            }
            const targetPos = getTransform(targetPlayer).method("get_position").invoke();
            const domeRadius = getDomeRadius(domeSize);
            const itemCount = 36; // Number of items to create dome
            const layers = getLayerCount(domeThickness);
            // Determine which prefab to spawn
            let prefabName = "";
            if (trapType === "metalball") {
                prefabName = "item_prefab/item_metal_ball";
            }
            else if (trapType === "christmaspresent") {
                prefabName = "item_prefab/item_christmas_present";
            }
            else {
                prefabName = "item_prefab/item_sellingmachine";
            }
            let spawnedCount = 0;
            const spawnedItems = [];
            // Create multiple layers of items for seamless coverage
            for (let layer = 0; layer < layers; layer++) {
                const layerHeight = (layer - (layers / 2)) * 1.2; // Centered vertical spacing
                // Create a ring of items at this layer
                for (let i = 0; i < itemCount; i++) {
                    const angle = (i / itemCount) * Math.PI * 2;
                    const spinOffset = domeSpinEnabled ? (Date.now() / 5000) * Math.PI * 2 : 0;
                    const finalAngle = angle + spinOffset;
                    const radius = domeRadius + (layer * 0.6);
                    const x = targetPos.fields.x + Math.cos(finalAngle) * radius;
                    const y = targetPos.fields.y + layerHeight + 1.5;
                    const z = targetPos.fields.z + Math.sin(finalAngle) * radius;
                    const spawnPos = [x, y, z];
                    try {
                        const spawned = spawnNetworkPrefab(prefabName, spawnPos, identityQuaternion);
                        if (spawned && !spawned.handle.isNull()) {
                            spawnedCount++;
                            spawnedItems.push(spawned);
                        }
                    }
                    catch (e) { }
                }
            }
            // Add top and bottom caps to seal the dome
            const capLayers = domeThickness === "triple" ? 3 : (domeThickness === "double" ? 2 : 1);
            for (let capLayer = 0; capLayer < capLayers; capLayer++) {
                for (let i = 0; i < 8; i++) {
                    const angle = (i / 8) * Math.PI * 2;
                    const spinOffset = domeSpinEnabled ? (Date.now() / 5000) * Math.PI * 2 : 0;
                    const finalAngle = angle + spinOffset;
                    const capRadius = (domeRadius * (1 - (capLayer * 0.2)));
                    const topX = targetPos.fields.x + Math.cos(finalAngle) * capRadius;
                    const topZ = targetPos.fields.z + Math.sin(finalAngle) * capRadius;
                    // Top cap
                    try {
                        const spawned = spawnNetworkPrefab(prefabName, [topX, targetPos.fields.y + 3.5 + (capLayer * 0.5), topZ], identityQuaternion);
                        if (spawned && !spawned.handle.isNull()) {
                            spawnedCount++;
                            spawnedItems.push(spawned);
                        }
                    }
                    catch (e) { }
                    // Bottom cap
                    try {
                        const spawned = spawnNetworkPrefab(prefabName, [topX, targetPos.fields.y - 0.5 - (capLayer * 0.5), topZ], identityQuaternion);
                        if (spawned && !spawned.handle.isNull()) {
                            spawnedCount++;
                            spawnedItems.push(spawned);
                        }
                    }
                    catch (e) { }
                }
            }
            // Handle auto-release timer
            if (domeAutoRelease > 0) {
                const releaseTime = domeAutoRelease * 1000; // Convert to milliseconds
                scheduleArcaneMainThread(releaseTime, () => {
                    // Try to remove spawned items (if game supports it)
                    for (let i = 0; i < spawnedItems.length; i++) {
                        try {
                            const go = spawnedItems[i].method("get_gameObject").invoke();
                            if (go && !go.isNull?.()) {
                                const destroy = Il2Cpp.domain.assembly("UnityEngine.CoreModule").image.class("UnityEngine.Object").method("Destroy", 1);
                                destroy.invoke(go);
                            }
                        }
                        catch (e) { }
                    }
                    sendNotification("Dome auto-released!", false);
                }, "dome auto-release");
                sendNotification("Dome will auto-release in " + domeAutoRelease + "s", false);
            }
            const sizeText = domeSize.charAt(0).toUpperCase() + domeSize.slice(1);
            const thicknessText = domeThickness.charAt(0).toUpperCase() + domeThickness.slice(1);
            sendNotification("Dome Created (" + sizeText + "/" + thicknessText + "): " + spawnedCount + " items!", true);
        }
        catch (e) {
            console.error("[Dome Trap] Error:", e);
            sendNotification("Dome trap failed: " + String(e).substring(0, 40), false);
        }
    }
    // ===== CATEGORY 22: TELEPORT MODS =====
