    // Variable to store saved position
    let savedPosition = null;
    // Function to copy player's current position
    function copyPlayerPosition() {
        try {
            const me = NetPlayer.method("get_localPlayer").invoke();
            if (!me || me.handle.isNull()) {
                sendNotification("Could not get your position!", false);
                return;
            }
            const pos = getTransform(me).method("get_position").invoke();
            // Save the Vector3 object directly
            savedPosition = pos;
            // Extract coordinates for display
            const x = pos.fields.x;
            const y = pos.fields.y;
            const z = pos.fields.z;
            sendNotification("Position Saved: (" + Math.round(x) + ", " + Math.round(y) + ", " + Math.round(z) + ")", true);
        }
        catch (e) {
            console.error("[Copy Position] Error:", e);
            sendNotification("Failed to copy position!", false);
        }
    }
    // Function to clear saved position
    function clearSavedPosition() {
        savedPosition = null;
        sendNotification("Saved position cleared!", false);
    }
    // Function to teleport all players to a location
    function teleportAllPlayersToLocation(location) {
        try {
            const me = NetPlayer.method("get_localPlayer").invoke();
            if (!me || me.handle.isNull()) {
                sendNotification("Could not get local player!", false);
                return;
            }
            let targetPos;
            // Special case: use player's current position for "My Position"
            if (location.special === "mypos" || (location.x === 0 && location.y === 0 && location.z === 0 && location.special === "mypos")) {
                targetPos = getTransform(me).method("get_position").invoke();
            }
            else if (location.fields) {
                // If it's already a Vector3 object (from saved position), use it directly
                targetPos = location;
            }
            else {
                // Create a vector for the target position (from map coordinates)
                const Vector3 = Il2Cpp.domain.assembly("UnityEngine.CoreModule").image.class("UnityEngine.Vector3");
                targetPos = Vector3.alloc();
                targetPos.method(".ctor").overload("System.Single", "System.Single", "System.Single").invoke(location.x, location.y, location.z);
            }
            // Get all players
            const playerDict = NetPlayer.field("playerIDToNetPlayer").value;
            const vals = playerDict.method("get_Values").invoke();
            const en = vals.method("GetEnumerator").invoke();
            let count = 0;
            // Teleport each player
            while (en.method("MoveNext").invoke()) {
                const p = en.method("get_Current").invoke();
                if (!p || p.handle.isNull())
                    continue;
                try {
                    p.method("RPC_Teleport").invoke(targetPos);
                    count++;
                }
                catch (e) {
                    console.error("[Teleport] Failed to teleport player:", e);
                }
            }
            sendNotification("Teleported " + count + " players!", false);
        }
        catch (e) {
            console.error("[Teleport All] Error:", e);
            sendNotification("Teleport Error: " + String(e).substring(0, 50), false);
        }
    }
