    // === SPACESHIP SPAWNING (Category 51) ===
    // Reads the game's SpaceshipDataSheet at runtime so EVERY ship (real display names +
    // prefabs) is listed, instead of a hardcoded guess. Falls back to the static list.
    let _shipListLoaded = false;
    function loadSpaceshipList() {
        if (_shipListLoaded) return;
        try {
            const dsClass = AssemblyCSharp.class("AnimalCompany.SpaceshipDataSheet");
            let sheet = null;
            try {
                const all = Resources.method("FindObjectsOfTypeAll", 1).inflate(dsClass).invoke();
                if (all && !all.isNull?.() && all.length > 0) sheet = all.get(0);
            } catch (_) { }
            if (!sheet || sheet.isNull?.()) {
                try {
                    const smc = AssemblyCSharp.class("AnimalCompany.ShipMachineController");
                    const ms = Object.method("FindObjectsByType", 1).inflate(smc).invoke(0);
                    if (ms && !ms.isNull?.() && ms.length > 0) sheet = ms.get(0).field("_dataSheet").value;
                } catch (_) { }
            }
            if (!sheet || sheet.isNull?.()) return; // not loaded yet; retry next call
            const count = sheet.method("get_Count").invoke();
            const list = [];
            for (let i = 0; i < count; i++) {
                try {
                    const e = sheet.method("GetByIndex", 1).invoke(i);
                    if (!e || e.isNull?.()) continue;
                    let nm = "Ship " + i;
                    try { const dn = e.field("displayName").value; if (dn && !dn.isNull?.()) nm = (dn.content || dn.toString()); } catch (_) { }
                    let pfName = null;
                    let pfNo = null;
                    try { const pf = e.field("shipPrefab").value; if (pf && !pf.isNull?.()) { pfNo = pf; pfName = pf.method("get_name").invoke().toString(); } } catch (_) { }
                    if (pfNo || pfName) list.push({ name: nm, prefab: pfName, no: pfNo });
                } catch (_) { }
            }
            if (list.length > 0) {
                _extraShips.forEach(x => list.push(x)); // keep UFOs available too
                spaceshipList.length = 0;
                list.forEach(x => spaceshipList.push(x));
                if (spaceshipIndex >= spaceshipList.length) spaceshipIndex = 0;
                _shipListLoaded = true;
                console.log("[Spaceship] Loaded " + list.length + " ships (incl. UFOs).");
            }
        } catch (e) { console.error("[Spaceship] load:", e); }
    }
    const shipAt = () => spaceshipList[spaceshipIndex % spaceshipList.length];
    // Prefer spawning the exact shipPrefab NetworkObject from the data sheet (no name matching);
    // fall back to the PrefabTable name lookup (used by UFOs / static entries).
    function spawnShip(pos, rot) {
        const s = shipAt();
        if (!s) return null;
        if (s.no && !s.no.isNull?.()) {
            const r = spawnNetworkObjectAt(s.no, pos, rot);
            if (r && !r.isNull?.()) return r;
        }
        return spawnNetworkPrefab(s.prefab, pos, rot);
    }
