    // === MONSTER RPCS (category 54) — control every live mob over the network ===
    // Enumerate live MobControllers and run fn on each, taking state authority first (that's what makes the
    // networked RPC / state write actually replicate to everyone). Dump-grounded (MobController @50xxx):
    // RPC_Teleport/RPC_Stun/RPC_SetColorHSV/RPC_SetRadioActive, SetTargetPlayer, SetNavAgentStopped/Speed/
    // SpeedBoost, ForceDie/SetDie, set_scaleModifier, SetRoamingTarget; get_Object -> NetworkObject.RequestStateAuthority.
    let _mobCtrlClass = null;
    function _forEachMob(fn, takeAuth) {
        let n = 0;
        try {
            if (!_mobCtrlClass) _mobCtrlClass = AssemblyCSharp.class("AnimalCompany.MobController");
            const arr = Object.method("FindObjectsByType", 1).inflate(_mobCtrlClass).invoke(0);
            if (!arr || arr.isNull?.()) return 0;
            for (let i = 0; i < arr.length; i++) {
                let mc = null;
                try { mc = arr.get(i); } catch (_) { continue; }
                if (!mc || mc.isNull?.()) continue;
                if (takeAuth) { try { const no = mc.method("get_Object").invoke(); if (no && !no.isNull?.()) no.method("RequestStateAuthority").invoke(); } catch (_) { } }
                try { fn(mc); n++; } catch (e) { console.error("[MobRPC] apply:", e); }
            }
        } catch (e) { console.error("[MobRPC] enumerate:", e); }
        return n;
    }
    function _localPlayerPos() {
        try { const lp = NetPlayer.method("get_localPlayer").invoke(); if (lp && !lp.isNull?.()) return getTransform(lp).method("get_position").invoke(); } catch (_) { }
        return null;
    }
