    let starOrbiters = [];
    let starOrbitPrefabs = [];
    function updateStarOrbit() {
        if (!starOrbitEnabled)
            return;
        try {
            const playerClass = NetPlayer;
            const currentPlayer = playerClass.field("_localPlayer").value;
            if (!currentPlayer || currentPlayer.isNull())
                return;
            const center = currentPlayer.method("get_head").invoke();
            if (!center || center.isNull())
                return;
            // Initialize star orbit on first enable
            if (starOrbiters.length === 0) {
                const spawnConfig = starOrbitPrefabTypes[starOrbitPrefabIndex];
                const spawnName = spawnConfig.name;
                const spawnType = spawnConfig.type;
                for (let i = 0; i < 5; i++) {
                    let angle = Math.PI * 2 / 5 * i;
                    const offset = Vector3.alloc();
                    offset.method(".ctor").overload("System.Single", "System.Single", "System.Single").invoke(Math.cos(angle) * starOrbitRadius, starOrbitHeight, Math.sin(angle) * starOrbitRadius);
                    let centerPos = center.method("get_position").invoke();
                    let spawnPos = Vector3.method("op_Addition").invoke(centerPos, [offset.field("x").value, offset.field("y").value, offset.field("z").value]);
                    const setupOrbit = (no) => {
                        if (!no || no.isNull?.()) return;
                        starOrbitPrefabs.push(no);
                        let go = no.method("get_gameObject").invoke();
                        if (!go || go.isNull?.()) return;
                        let tf = go.method("get_transform").invoke();
                        starOrbiters.push({ transform: tf, angle });
                    };
                    try {
                        if (spawnType === "item") {
                            spawnItemThen(spawnName, spawnPos, Quaternion.method("get_identity").invoke(), setupOrbit);
                        }
                        else {
                            setupOrbit(spawnNetworkPrefab(spawnName, spawnPos, Quaternion.method("get_identity").invoke()));
                        }
                    }
                    catch (_) { }
                }
            }
            // Update star orbit rotation
            let delta = Time.method("get_deltaTime").invoke();
            let centerPos = center.method("get_position").invoke();
            for (let orb of starOrbiters) {
                if (!orb.transform || orb.transform.isNull?.())
                    continue;
                orb.angle += starOrbitSpeed * delta;
                try {
                    const offset = Vector3.alloc();
                    if (!offset || offset.isNull?.())
                        continue;
                    // Pass constructor params as array
                    offset.method(".ctor").overload("System.Single", "System.Single", "System.Single").invoke([
                        Math.cos(orb.angle) * starOrbitRadius,
                        starOrbitHeight,
                        Math.sin(orb.angle) * starOrbitRadius
                    ]);
                    // Use op_Addition with the offset object directly
                    let newPos = Vector3.method("op_Addition").invoke(centerPos, offset);
                    if (newPos && !newPos.isNull?.()) {
                        orb.transform.method("set_position").invoke(newPos);
                    }
                }
                catch (e) {
                    console.error("[STAR ORBIT] Position update error:", e);
                    continue;
                }
            }
        }
        catch (e) {
            console.error("[STAR ORBIT] Error:", e);
        }
    }
